  // target ที่ควรตั้งบนตู้ควบคุมจริง = อุณหภูมิ Pill ที่ AI แนะนำ ลบด้วยส่วนต่าง Pill-ตู้ควบคุม
  // ช่วงนิ่ง (stable_gap_c) เพราะ Pill (เบียร์จริง) กับตู้ควบคุม (อากาศ) มักมีส่วนต่างค้างอยู่
  // เสมอแม้ตอนนิ่งแล้ว ถ้าไม่มีข้อมูลส่วนต่างพอ (ยังไม่นิ่ง/เพิ่งเริ่ม batch) จะไม่แนะนำปุ่มให้
  let recommendedControllerTargetC = (recommendedPillTempC != null && src.stable_gap_c != null)
    ? round(recommendedPillTempC - src.stable_gap_c, 2)
    : null;

  // เกณฑ์ต่ำสุดที่ต่างจาก target ปัจจุบันถึงจะแนะนำ (°C) — กัน noise เล็กน้อยจากการคำนวณ
  // stable_gap_c ใหม่ทุกรอบ ทำให้แนะนำ target ที่แทบไม่ต่างจากที่ตั้งไว้แล้วซ้ำๆ (เจอจริง 18
  // ส.ค. batch Weizen: target ตั้งไว้ 1.67°C แต่แนะนำ 1.68°C แล้วรอบถัดมาแนะนำ 1.62°C อีก
  // ทั้งที่ไม่มีอะไรใหม่ให้ action จริง)
  const MIN_TARGET_CHANGE_C = 2.5;
  if (
    recommendedControllerTargetC != null &&
    src.target_temperature_c != null &&
    Math.abs(recommendedControllerTargetC - src.target_temperature_c) < MIN_TARGET_CHANGE_C
  ) {
    recommendedPillTempC = null;
    recommendedControllerTargetC = null;
  }

  // ประมาณเวลาที่ Pill จะถึงอุณหภูมิเป้าหมายที่แนะนำ จากอัตราการเปลี่ยนแปลง
  // ล่าสุด (6 ชม., คำนวณไว้ที่ Build AI Prompt) — คำนวณด้วยเลขล้วนๆ ไม่ให้ AI
  // ทายเวลา กันเพี้ยน ถ้าอัตรายังไม่ชัดหรือทิศทางไม่ตรงกับที่ต้องการปรับ
  // (เช่น อยาก d-rest แต่ Pill กำลังลดอยู่) จะบอกตรงๆ ว่ายังประมาณไม่ได้
  // แทนที่จะโชว์เลขมั่ว
  let pillEtaText = null;
  if (recommendedPillTempC != null && src.temperature_c != null) {
    const diffC = recommendedPillTempC - src.temperature_c;
