    if (Math.abs(diffC) < 0.05) {
      pillEtaText = null; // ใกล้ target อยู่แล้ว ไม่ต้องประมาณเวลา
    } else if (rate == null || Math.abs(rate) < MIN_RATE_C_PER_HOUR || Math.sign(rate) !== Math.sign(diffC)) {
      pillEtaText = 'ยังไม่เห็นแนวโน้มอุณหภูมิ Pill ขยับชัดเจนพอจะประมาณเวลาได้';
    } else {
      const etaHours = Math.abs(diffC) / Math.abs(rate);
      const referenceMs = src.analysis_time_iso ? new Date(src.analysis_time_iso).getTime() : Date.now();
      const bkk = new Date(referenceMs + etaHours * 3600000 + 7 * 3600000);
      const dd = String(bkk.getUTCDate()).padStart(2, '0');
      const mm = String(bkk.getUTCMonth() + 1).padStart(2, '0');
      const yyyy = bkk.getUTCFullYear();
      const hh = String(bkk.getUTCHours()).padStart(2, '0');
      const min = String(bkk.getUTCMinutes()).padStart(2, '0');
      pillEtaText = `คาดว่าจะถึงประมาณ ${dd}/${mm}/${yyyy} ${hh}:${min} (~${etaHours.toFixed(0)} ชม. ที่อัตราปัจจุบัน ~${Math.abs(rate).toFixed(2)}°C/ชม.)`;
    }
  }
  results.push({
    json: {
      batch_id: src.batch_id,
      beer_name: src.beer_name,
      previous_phase: src.current_phase,
      detected_phase: phase,
      reasoning,
      gravity_sg: round(src.gravity_sg, 3),
      temperature_c: round(src.temperature_c, 2),
      gravity_velocity: src.gravity_velocity,
      controller_temp_c: round(src.controller_temp_c, 2),
      target_temperature_c: round(src.target_temperature_c, 2),
      abv_percent: round(src.abv_percent, 2),
      pill_time_utc: src.pill_time_utc ?? null,
      controller_time_utc: src.controller_time_utc ?? null,
      next_phase: nextPhase,
      prep_actions_text: prepActionsText,
      phase_timeline_text: phaseTimelineText,
      should_send_prep_alert: shouldSendPrepAlert,
      recommended_pill_temp_c: recommendedPillTempC,
      recommended_controller_target_c: recommendedControllerTargetC,
      pill_eta_text: pillEtaText,
      batch_ready_to_package: batchReadyToPackage
    }
  });
});
return results;
